import type { TimestampLike } from './types';

export type TimeInput = TimestampLike | Date | number | null | undefined;

/** Convert any supported timestamp shape to epoch milliseconds. */
export function toMillis(value: TimeInput): number | null {
  if (value == null) return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  if (value instanceof Date) return value.getTime();
  if (typeof value.toMillis === 'function') return value.toMillis();
  return null;
}

/** "45 s", "12 min", "1 h 05 min". */
export function formatDuration(seconds: number | null | undefined): string {
  if (seconds == null || !Number.isFinite(seconds)) return '—';
  const total = Math.max(0, Math.round(seconds));
  if (total < 60) return '< 1 min';
  const minutes = Math.round(total / 60);
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest === 0 ? `${hours} h` : `${hours} h ${String(rest).padStart(2, '0')} min`;
}

/** "850 m", "4.2 km", "18 km". */
export function formatDistance(meters: number | null | undefined): string {
  if (meters == null || !Number.isFinite(meters)) return '—';
  if (meters < 1000) return `${Math.max(0, Math.round(meters / 10) * 10)} m`;
  const km = meters / 1000;
  return km < 10 ? `${km.toFixed(1)} km` : `${Math.round(km)} km`;
}

const CLOCK_SKEW_SECONDS = 120;

/** "just now", "5 min ago", "3 h ago", "yesterday", "12 Nov". */
export function formatRelativeTime(value: TimeInput, now = Date.now()): string {
  const millis = toMillis(value);
  if (millis == null) return '—';
  const diffSeconds = Math.round((now - millis) / 1000);
  // Server timestamps can run slightly ahead of the device clock; that is still "just now".
  if (diffSeconds < 0 && diffSeconds > -CLOCK_SKEW_SECONDS) return 'just now';
  if (diffSeconds < 0) {
    const ahead = -diffSeconds;
    if (ahead < 60) return 'in < 1 min';
    if (ahead < 3600) return `in ${Math.round(ahead / 60)} min`;
    return `in ${formatDuration(ahead)}`;
  }
  if (diffSeconds < 45) return 'just now';
  if (diffSeconds < 3600) return `${Math.max(1, Math.round(diffSeconds / 60))} min ago`;
  if (diffSeconds < 86_400) return `${Math.round(diffSeconds / 3600)} h ago`;
  if (diffSeconds < 172_800) return 'yesterday';
  return formatDate(millis);
}

/** "14:05" in the device locale. */
export function formatClock(value: TimeInput): string {
  const millis = toMillis(value);
  if (millis == null) return '—';
  return new Date(millis).toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' });
}

/** "12 Nov" (or "12 Nov 2025" when not in the current year). */
export function formatDate(value: TimeInput): string {
  const millis = toMillis(value);
  if (millis == null) return '—';
  const date = new Date(millis);
  const sameYear = date.getFullYear() === new Date().getFullYear();
  return date.toLocaleDateString(undefined, {
    day: 'numeric',
    month: 'short',
    ...(sameYear ? {} : { year: 'numeric' }),
  });
}

/** "12 Nov, 14:05". */
export function formatDateTime(value: TimeInput): string {
  const millis = toMillis(value);
  if (millis == null) return '—';
  return `${formatDate(millis)}, ${formatClock(millis)}`;
}

/** Clock time `seconds` from now: "ETA 14:35". */
export function formatEta(secondsFromNow: number | null | undefined, now = Date.now()): string {
  if (secondsFromNow == null || !Number.isFinite(secondsFromNow)) return '—';
  return formatClock(now + secondsFromNow * 1000);
}

export function formatCurrency(amount: number | null | undefined, currency = 'INR'): string {
  if (amount == null || !Number.isFinite(amount)) return '—';
  try {
    return new Intl.NumberFormat(undefined, {
      style: 'currency',
      currency,
      maximumFractionDigits: amount % 1 === 0 ? 0 : 2,
    }).format(amount);
  } catch {
    return `${currency} ${amount.toFixed(2)}`;
  }
}

export function initials(name: string | null | undefined): string {
  const parts = (name ?? '').trim().split(/\s+/).filter(Boolean);
  if (parts.length === 0) return '?';
  const first = parts[0]![0] ?? '';
  const last = parts.length > 1 ? (parts[parts.length - 1]![0] ?? '') : '';
  return (first + last).toUpperCase();
}

export function firstName(name: string | null | undefined): string {
  return (name ?? '').trim().split(/\s+/)[0] || 'Customer';
}

/** "+91 98••• ••210" — enough to recognise a number without exposing it. */
export function maskPhone(phone: string | null | undefined): string {
  if (!phone) return '—';
  const digits = phone.replace(/[^\d+]/g, '');
  if (digits.length <= 6) return digits;
  return `${digits.slice(0, 5)}•••••${digits.slice(-3)}`;
}

export function pluralize(count: number, singular: string, plural = `${singular}s`): string {
  return `${count} ${count === 1 ? singular : plural}`;
}

/** Start of the local day for `value`, in epoch ms. */
export function startOfDay(value: number = Date.now()): number {
  const date = new Date(value);
  date.setHours(0, 0, 0, 0);
  return date.getTime();
}
