/** Steps shown in progress trackers (driver app, tracking page). */
export const PROGRESS_STEPS: readonly DeliveryStatus[] = [
  'assigned',
  'picked_up',
  'in_transit',
  'arrived',
  'delivered',
];

const DRIVER_TRANSITIONS: Partial<Record<DeliveryStatus, readonly DeliveryStatus[]>> = {
  // "unassigned" from "assigned" means the driver declined the job.
  assigned: ['accepted', 'unassigned'],
  accepted: ['picked_up', 'in_transit', 'failed'],
  picked_up: ['in_transit', 'failed'],
  // "picked_up" from "in_transit" parks the trip when the driver switches to another stop.
  in_transit: ['arrived', 'delivered', 'failed', 'picked_up'],
  arrived: ['delivered', 'failed', 'in_transit'],
};

const STAFF_TRANSITIONS: Partial<Record<DeliveryStatus, readonly DeliveryStatus[]>> = {
  unassigned: ['assigned', 'cancelled'],
  assigned: ['unassigned', 'assigned', 'delivered', 'failed', 'cancelled'],
  accepted: ['unassigned', 'assigned', 'delivered', 'failed', 'cancelled'],
  picked_up: ['unassigned', 'assigned', 'delivered', 'failed', 'cancelled'],
  in_transit: ['unassigned', 'assigned', 'delivered', 'failed', 'cancelled'],
  arrived: ['unassigned', 'assigned', 'delivered', 'failed', 'cancelled'],
  failed: ['unassigned', 'assigned', 'cancelled'],
};

export function allowedTransitions(from: DeliveryStatus, actor: TransitionActor): readonly DeliveryStatus[] {
  const table = actor === 'driver' ? DRIVER_TRANSITIONS : STAFF_TRANSITIONS;
  return table[from] ?? [];
}

export function canTransition(from: DeliveryStatus, to: DeliveryStatus, actor: TransitionActor): boolean {
  return allowedTransitions(from, actor).includes(to);
}

export function isActiveStatus(status: DeliveryStatus): boolean {
  return ACTIVE_STATUSES.includes(status);
}

export function isOpenStatus(status: DeliveryStatus): boolean {
  return OPEN_STATUSES.includes(status);
}

export function isTerminalStatus(status: DeliveryStatus): boolean {
  return TERMINAL_STATUSES.includes(status);
}

export function statusLabel(status: DeliveryStatus): string {
  return STATUS_META[status]?.label ?? status;
}

export interface DriverAction {
  /** Status the action moves the delivery to. */
  to: DeliveryStatus;
  label: string;
  /** Needs the proof-of-delivery flow instead of a plain status update. */
  requiresProof?: boolean;
}

/** The single primary action a driver sees for a delivery. */
export function primaryDriverAction(status: DeliveryStatus): DriverAction | null {
  switch (status) {
    case 'assigned':
      return { to: 'accepted', label: 'Accept delivery' };
    case 'accepted':
      return { to: 'picked_up', label: 'Mark as picked up' };
    case 'picked_up':
      return { to: 'in_transit', label: 'Start trip' };
    case 'in_transit':
      return { to: 'arrived', label: "I've arrived" };
    case 'arrived':
      return { to: 'delivered', label: 'Complete delivery', requiresProof: true };
    default:
      return null;
  }
}

/** Timestamp field stamped on the delivery when it enters a status. */
export const STATUS_TIMESTAMP_FIELD: Partial<Record<DeliveryStatus, string>> = {
  assigned: 'assignedAt',
  accepted: 'acceptedAt',
  picked_up: 'pickedUpAt',
  in_transit: 'startedAt',
  arrived: 'arrivedAt',
  delivered: 'deliveredAt',
  failed: 'failedAt',
  cancelled: 'cancelledAt',
};

/** Index of a status within PROGRESS_STEPS (accepted counts as assigned). */
export function progressIndex(status: DeliveryStatus): number {
  const normalized = status === 'accepted' ? 'assigned' : status;
  return PROGRESS_STEPS.indexOf(normalized);
}
