/**
 * Multi-stop route optimizer.
 *
 * Builds an initial tour with a priority-aware nearest-neighbour heuristic, then improves it with
 * 2-opt (segment reversal) and relocate moves until no move lowers the cost or the time budget
 * runs out. The cost is total travel time plus penalties:
 *
 *   cost = Σ travel + Σ (priorityWeight − 1) · arrival · PRIORITY_FACTOR + Σ lateSeconds · LATE_FACTOR
 *
 * (PRIORITY_FACTOR = 0.5, LATE_FACTOR = 5.)
 *
 * With every stop at "normal" priority and no time windows, this is a shortest open path
 * (a travelling salesman path without returning to the depot). Asymmetric matrices, such as
 * traffic-aware travel times, are fully supported because each candidate is evaluated end to end.
 */
import { DEFAULT_SERVICE_SECONDS, PRIORITY_META } from './constants';
import { DEFAULT_CITY_SPEED_KMH, estimateDriveSeconds, estimateRoadMeters, haversineMeters } from './geo';
import type { LatLng, Priority } from './types';

/**
 * Seconds of penalty per second an above-normal stop waits, per unit of extra priority weight.
 * With urgent (weight 4) every second of delay costs 1.5 s, so the optimizer will accept
 * a meaningful detour to serve urgent customers first.
 */
const PRIORITY_FACTOR = 0.5;
const LATE_FACTOR = 5;
const EPSILON = 1e-6;

export interface TravelMatrix {
  /** `seconds[i][j]` is the travel time from point `i` to point `j`. Index 0 is the origin. */
  seconds: number[][];
  meters: number[][];
}

export interface OptimizerStop {
  id: string;
  location: LatLng;
  priority?: Priority;
  /** Earliest useful arrival (epoch ms). The driver waits if early. */
  windowStart?: number | null;
  /** Latest acceptable arrival (epoch ms). Late arrivals are penalized. */
  windowEnd?: number | null;
  /** Time spent at the stop, in seconds. */
  serviceSeconds?: number;
}

export interface OptimizeOptions {
  /** Epoch ms when the route starts. Defaults to `Date.now()`. */
  startTime?: number;
  /** Stop that must stay first, typically the one the driver is already heading to. */
  lockedFirstId?: string | null;
  defaultServiceSeconds?: number;
  /** Upper bound for local-search time, in milliseconds. */
  timeBudgetMs?: number;
}

export interface PlannedLeg {
  id: string;
  /** Index into the `stops` array passed to `optimizeStops`. */
  stopIndex: number;
  legSeconds: number;
  legMeters: number;
  /** Seconds after the start when the driver arrives at this stop. */
  arrivalOffsetSeconds: number;
  /** Seconds after the window end, 0 when on time or without a window. */
  lateSeconds: number;
}

export interface OptimizedRoute {
  legs: PlannedLeg[];
  /** Sum of driving time across all legs. */
  totalSeconds: number;
  totalMeters: number;
  /** Seconds until the last stop is finished, including service and waiting time. */
  finishOffsetSeconds: number;
  cost: number;
}

/** Build a matrix from straight-line distances. Index 0 of `points` is the origin. */
export function buildEstimateMatrix(
  points: readonly LatLng[],
  speedKmh = DEFAULT_CITY_SPEED_KMH,
): TravelMatrix {
  const seconds: number[][] = [];
  const meters: number[][] = [];
  for (let i = 0; i < points.length; i += 1) {
    const secondsRow: number[] = [];
    const metersRow: number[] = [];
    for (let j = 0; j < points.length; j += 1) {
      const road = i === j ? 0 : estimateRoadMeters(haversineMeters(points[i]!, points[j]!));
      metersRow.push(road);
      secondsRow.push(estimateDriveSeconds(road, speedKmh));
    }
    seconds.push(secondsRow);
    meters.push(metersRow);
  }
  return { seconds, meters };
}

/**
 * Replace missing or invalid matrix cells (e.g. "route not found" from a provider) with estimates,
 * so the optimizer always gets a complete matrix.
 */
export function fillMatrixGaps(
  matrix: TravelMatrix,
  points: readonly LatLng[],
  speedKmh = DEFAULT_CITY_SPEED_KMH,
): TravelMatrix {
  const estimate = buildEstimateMatrix(points, speedKmh);
  const pick = (value: number | undefined, fallback: number) =>
    typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : fallback;
  return {
    seconds: estimate.seconds.map((row, i) =>
      row.map((fallback, j) => (i === j ? 0 : pick(matrix.seconds[i]?.[j], fallback))),
    ),
    meters: estimate.meters.map((row, i) =>
      row.map((fallback, j) => (i === j ? 0 : pick(matrix.meters[i]?.[j], fallback))),
    ),
  };
}

export function optimizeStops(
  stops: readonly OptimizerStop[],
  matrix: TravelMatrix,
  options: OptimizeOptions = {},
): OptimizedRoute {
  const size = stops.length + 1;
  if (matrix.seconds.length !== size || matrix.meters.length !== size) {
    throw new Error(`Matrix must be ${size}x${size} (origin + ${stops.length} stops).`);
  }

  if (stops.length === 0) {
    return { legs: [], totalSeconds: 0, totalMeters: 0, finishOffsetSeconds: 0, cost: 0 };
  }

  const startTime = options.startTime ?? Date.now();
  const defaultService = options.defaultServiceSeconds ?? DEFAULT_SERVICE_SECONDS;
  const timeBudgetMs = options.timeBudgetMs ?? 250;
  const lockedIndex = options.lockedFirstId
    ? stops.findIndex((stop) => stop.id === options.lockedFirstId)
    : -1;

  // Orders hold matrix indices (1..n); stop i lives at matrix index i + 1.
  const weightOf = (matrixIndex: number) =>
    PRIORITY_META[stops[matrixIndex - 1]?.priority ?? 'normal'].weight;

  const cost = (order: readonly number[]): number => {
    let clock = 0;
    let travel = 0;
    let penalty = 0;
    let previous = 0;
    for (const current of order) {
      const stop = stops[current - 1]!;
      const leg = matrix.seconds[previous]![current]!;
      clock += leg;
      travel += leg;
      if (stop.windowStart != null) {
        const earliest = (stop.windowStart - startTime) / 1000;
        if (clock < earliest) clock = earliest;
      }
      penalty += (weightOf(current) - 1) * clock * PRIORITY_FACTOR;
      if (stop.windowEnd != null) {
        const late = clock - (stop.windowEnd - startTime) / 1000;
        if (late > 0) penalty += late * LATE_FACTOR;
      }
      clock += stop.serviceSeconds ?? defaultService;
      previous = current;
    }
    return travel + penalty;
  };

  let order = nearestNeighbourOrder(stops.length, matrix, weightOf, lockedIndex);
  const lockStart = lockedIndex >= 0 ? 1 : 0;
  order = improve(order, lockStart, cost, timeBudgetMs);

  return materialize(order, stops, matrix, startTime, defaultService, cost(order));
}

function nearestNeighbourOrder(
  count: number,
  matrix: TravelMatrix,
  weightOf: (matrixIndex: number) => number,
  lockedIndex: number,
): number[] {
  const remaining = new Set<number>();
  for (let index = 1; index <= count; index += 1) remaining.add(index);

  const order: number[] = [];
  let current = 0;
  if (lockedIndex >= 0) {
    current = lockedIndex + 1;
    order.push(current);
    remaining.delete(current);
  }

  while (remaining.size > 0) {
    let bestIndex = -1;
    let bestScore = Number.POSITIVE_INFINITY;
    for (const candidate of remaining) {
      // Higher-priority stops look "closer", so they tend to be visited earlier.
      const score = matrix.seconds[current]![candidate]! / weightOf(candidate);
      if (score < bestScore - EPSILON || (Math.abs(score - bestScore) <= EPSILON && candidate < bestIndex)) {
        bestScore = score;
        bestIndex = candidate;
      }
    }
    order.push(bestIndex);
    remaining.delete(bestIndex);
    current = bestIndex;
  }
  return order;
}

function improve(
  initial: number[],
  lockStart: number,
  cost: (order: readonly number[]) => number,
  timeBudgetMs: number,
): number[] {
  const deadline = Date.now() + timeBudgetMs;
  let order = initial;
  let best = cost(order);
  const length = order.length;

  let improved = true;
  while (improved && Date.now() < deadline) {
    improved = false;

    // 2-opt: reverse the segment order[i..j].
    for (let i = lockStart; i < length - 1 && !improved; i += 1) {
      for (let j = i + 1; j < length && !improved; j += 1) {
        const candidate = [...order.slice(0, i), ...order.slice(i, j + 1).reverse(), ...order.slice(j + 1)];
        const candidateCost = cost(candidate);
        if (candidateCost < best - EPSILON) {
          order = candidate;
          best = candidateCost;
          improved = true;
        }
      }
    }

    // Relocate: move a single stop to another position.
    for (let i = lockStart; i < length && !improved; i += 1) {
      for (let j = lockStart; j < length && !improved; j += 1) {
        if (i === j) continue;
        const candidate = order.slice();
        const [moved] = candidate.splice(i, 1);
        candidate.splice(j, 0, moved!);
        const candidateCost = cost(candidate);
        if (candidateCost < best - EPSILON) {
          order = candidate;
          best = candidateCost;
          improved = true;
        }
      }
    }
  }
  return order;
}

function materialize(
  order: readonly number[],
  stops: readonly OptimizerStop[],
  matrix: TravelMatrix,
  startTime: number,
  defaultService: number,
  finalCost: number,
): OptimizedRoute {
  const legs: PlannedLeg[] = [];
  let clock = 0;
  let totalSeconds = 0;
  let totalMeters = 0;
  let previous = 0;

  for (const current of order) {
    const stop = stops[current - 1]!;
    const legSeconds = matrix.seconds[previous]![current]!;
    const legMeters = matrix.meters[previous]![current]!;
    clock += legSeconds;
    if (stop.windowStart != null) {
      const earliest = (stop.windowStart - startTime) / 1000;
      if (clock < earliest) clock = earliest;
    }
    const lateSeconds = stop.windowEnd != null ? Math.max(0, clock - (stop.windowEnd - startTime) / 1000) : 0;
    legs.push({
      id: stop.id,
      stopIndex: current - 1,
      legSeconds,
      legMeters,
      arrivalOffsetSeconds: clock,
      lateSeconds,
    });
    totalSeconds += legSeconds;
    totalMeters += legMeters;
    clock += stop.serviceSeconds ?? defaultService;
    previous = current;
  }

  return { legs, totalSeconds, totalMeters, finishOffsetSeconds: clock, cost: finalCost };
}
