/**
 * Customer-facing commerce: catalog, cart pricing, orders, addresses and reviews.
 *
 * Every price shown in the customer app is computed with `priceCart` and recomputed on the
 * server from catalog prices when the order is placed, so the two always agree and the client
 * can never set its own prices.
 */
import { isValidLatLng } from './geo';
import type { DeliveryStatus, LatLng, TimestampLike } from './types';
import { cleanText, normalizePhone, type ValidationResult } from './validation';

export const CURRENCY = 'INR';

export interface Category {
  id: string;
  name: string;
  /** Illustration key in @instasupply/art (category icon). */
  iconKey: string;
  /** Pastel background behind the icon. */
  tint: string;
  /** Accent colour of the icon. */
  accent: string;
  sortOrder: number;
}

export interface Product {
  id: string;
  name: string;
  categoryId: string;
  /** Pack size shown under the name, e.g. "1 kg", "dozen", "500 ml". */
  unit: string;
  price: number;
  /** Strike-through price when discounted. */
  mrp: number | null;
  description: string;
  /** Illustration key in @instasupply/art; used when there is no uploaded photo. */
  imageKey: string | null;
  imageUrl: string | null;
  badge: 'new' | 'bestseller' | 'organic' | null;
  rating: number;
  ratingCount: number;
  stock: number;
  active: boolean;
  featured: boolean;
  /** Lower-cased words for prefix search. */
  searchTerms: string[];
  createdAt?: TimestampLike;
  updatedAt?: TimestampLike;
}

export interface CartLine {
  productId: string;
  quantity: number;
}

export const MAX_CART_LINES = 50;
export const MAX_QUANTITY_PER_LINE = 20;

export type PaymentMethod = 'cod' | 'card';
export type PaymentStatus = 'cod_pending' | 'collected' | 'paid' | 'refund_pending' | 'refunded';

export type OrderStatus =
  | 'placed'
  | 'confirmed'
  | 'packed'
  | 'out_for_delivery'
  | 'delivered'
  | 'failed'
  | 'cancelled';

export interface OrderItem {
  productId: string;
  name: string;
  unit: string;
  price: number;
  quantity: number;
  imageKey: string | null;
  imageUrl: string | null;
  lineTotal: number;
}

export interface AddressFields {
  label: string;
  name: string;
  phone: string;
  line1: string;
  line2: string | null;
  landmark: string | null;
  city: string;
  zip: string;
  location: LatLng | null;
}

export interface Address extends AddressFields {
  id: string;
  isDefault: boolean;
  createdAt?: TimestampLike;
  updatedAt?: TimestampLike;
}

export interface SavedCard {
  id: string;
  brand: CardBrand;
  last4: string;
  expMonth: number;
  expYear: number;
  holder: string;
  isDefault: boolean;
  createdAt?: TimestampLike;
}

export interface Order {
  id: string;
  /** Same human reference as the linked delivery, e.g. IS-10042. */
  number: string;
  customerId: string;
  customerName: string;
  items: OrderItem[];
  itemCount: number;
  subtotal: number;
  deliveryFee: number;
  discount: number;
  total: number;
  currency: typeof CURRENCY;
  promoCode: string | null;
  paymentMethod: PaymentMethod;
  paymentStatus: PaymentStatus;
  paymentRef: string | null;
  card: { brand: CardBrand; last4: string } | null;
  address: AddressFields;
  notes: string | null;
  status: OrderStatus;
  /** When each status was reached (epoch-free Firestore timestamps keyed by status). */
  statusAt: Partial<Record<OrderStatus, TimestampLike>>;
  deliveryId: string;
  /** Token of the public tracking document (live driver position, ETA, hand-off code). */
  trackingToken: string;
  cancelReason: string | null;
  reviewed?: boolean;
  createdAt: TimestampLike;
  updatedAt: TimestampLike;
}

export interface Review {
  /** Equal to the reviewer's uid: one review per customer per product. */
  id: string;
  productId: string;
  userId: string;
  userName: string;
  rating: number;
  text: string;
  createdAt: TimestampLike;
  updatedAt: TimestampLike;
}

// ---------- order status ----------

export const ORDER_PROGRESS: readonly OrderStatus[] = [
  'placed',
  'confirmed',
  'packed',
  'out_for_delivery',
  'delivered',
];

/** Orders still moving through fulfilment (staff queues and badges). */
export const ORDER_OPEN_STATUSES: readonly OrderStatus[] = ['placed', 'confirmed', 'packed', 'out_for_delivery'];

export const ORDER_STATUS_META: Record<
  OrderStatus,
  { label: string; description: string; tone: 'neutral' | 'info' | 'brand' | 'success' | 'danger' | 'warning' }
> = {
  placed: { label: 'Order placed', description: 'We received your order', tone: 'info' },
  confirmed: { label: 'Order confirmed', description: 'A delivery partner has been assigned', tone: 'info' },
  packed: { label: 'Order shipped', description: 'Your groceries are packed and with the driver', tone: 'brand' },
  out_for_delivery: { label: 'Out for delivery', description: 'Your driver is on the way', tone: 'brand' },
  delivered: { label: 'Order delivered', description: 'Enjoy your groceries!', tone: 'success' },
  failed: { label: 'Delivery attempt failed', description: 'We will contact you to reschedule', tone: 'danger' },
  cancelled: { label: 'Cancelled', description: 'This order was cancelled', tone: 'neutral' },
};

/** The customer-facing order status for a delivery status. */
export function orderStatusForDelivery(status: DeliveryStatus): OrderStatus {
  switch (status) {
    case 'unassigned':
      return 'placed';
    case 'assigned':
    case 'accepted':
      return 'confirmed';
    case 'picked_up':
      return 'packed';
    case 'in_transit':
    case 'arrived':
      return 'out_for_delivery';
    case 'delivered':
      return 'delivered';
    case 'failed':
      return 'failed';
    case 'cancelled':
      return 'cancelled';
  }
}

/** Customers can cancel until the driver has picked the order up. */
export function canCustomerCancel(status: OrderStatus): boolean {
  return status === 'placed' || status === 'confirmed';
}

export function isOrderOpen(status: OrderStatus): boolean {
  return status !== 'delivered' && status !== 'cancelled';
}

// ---------- pricing ----------

export const FREE_DELIVERY_THRESHOLD = 499;
export const DELIVERY_FEE = 30;

export interface Promo {
  code: string;
  label: string;
  percent: number;
  maxDiscount: number;
  minSubtotal: number;
  firstOrderOnly: boolean;
}

export const PROMOS: Record<string, Promo> = {
  FIRST20: {
    code: 'FIRST20',
    label: '20% off your first order (up to ₹100)',
    percent: 20,
    maxDiscount: 100,
    minSubtotal: 199,
    firstOrderOnly: true,
  },
  FRESH10: {
    code: 'FRESH10',
    label: '10% off orders above ₹799 (up to ₹150)',
    percent: 10,
    maxDiscount: 150,
    minSubtotal: 799,
    firstOrderOnly: false,
  },
};

export function findPromo(code: string | null | undefined): Promo | null {
  if (!code) return null;
  return PROMOS[code.trim().toUpperCase()] ?? null;
}

const roundMoney = (value: number) => Math.round(value * 100) / 100;

export interface PricedCart {
  itemCount: number;
  subtotal: number;
  deliveryFee: number;
  discount: number;
  total: number;
  /** Set when a promo was requested but does not apply (and why). */
  promoError: string | null;
  promo: Promo | null;
  /** Amount still needed for free delivery (0 when already free). */
  amountToFreeDelivery: number;
}

/**
 * Price a cart. `isFirstOrder` decides first-order-only promos; the server passes the truth,
 * the client passes its best guess for display.
 */
export function priceCart(
  lines: readonly { price: number; quantity: number }[],
  options: { promoCode?: string | null; isFirstOrder?: boolean } = {},
): PricedCart {
  const subtotal = roundMoney(lines.reduce((sum, line) => sum + line.price * line.quantity, 0));
  const itemCount = lines.reduce((sum, line) => sum + line.quantity, 0);
  const deliveryFee = subtotal === 0 || subtotal >= FREE_DELIVERY_THRESHOLD ? 0 : DELIVERY_FEE;

  let promo: Promo | null = null;
  let promoError: string | null = null;
  let discount = 0;
  if (options.promoCode) {
    const candidate = findPromo(options.promoCode);
    if (!candidate) promoError = 'That code is not valid.';
    else if (candidate.firstOrderOnly && options.isFirstOrder === false) promoError = `${candidate.code} is for your first order only.`;
    else if (subtotal < candidate.minSubtotal) promoError = `Add items worth ₹${candidate.minSubtotal} to use ${candidate.code}.`;
    else {
      promo = candidate;
      discount = roundMoney(Math.min(candidate.maxDiscount, (subtotal * candidate.percent) / 100));
    }
  }

  return {
    itemCount,
    subtotal,
    deliveryFee,
    discount,
    total: roundMoney(Math.max(0, subtotal + deliveryFee - discount)),
    promoError,
    promo,
    amountToFreeDelivery: subtotal === 0 ? FREE_DELIVERY_THRESHOLD : roundMoney(Math.max(0, FREE_DELIVERY_THRESHOLD - subtotal)),
  };
}

export function discountPercent(product: Pick<Product, 'price' | 'mrp'>): number | null {
  if (!product.mrp || product.mrp <= product.price) return null;
  return Math.round(((product.mrp - product.price) / product.mrp) * 100);
}

/**
 * Search keys for a product: every prefix (2+ letters) of every word in its name and extra
 * terms, lower-cased. Lets a single `array-contains` query do prefix search ("man" → mango).
 */
export function buildSearchTerms(name: string, extra: readonly string[] = []): string[] {
  const words = [name, ...extra]
    .join(' ')
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 2);
  const terms = new Set<string>();
  for (const word of words) {
    for (let length = 2; length <= Math.min(word.length, 15); length += 1) terms.add(word.slice(0, length));
  }
  return [...terms];
}

/** The search key to query for a user's search text (its longest word), or null if too short. */
export function searchKeyFor(text: string): string | null {
  const words = text
    .toLowerCase()
    .split(/[^a-z0-9]+/)
    .filter((word) => word.length >= 2)
    .sort((a, b) => b.length - a.length);
  return words[0]?.slice(0, 15) ?? null;
}

// ---------- cards (test-mode payments) ----------

export type CardBrand = 'visa' | 'mastercard' | 'rupay' | 'amex' | 'card';

export function detectCardBrand(number: string): CardBrand {
  const digits = number.replace(/\D/g, '');
  if (/^4/.test(digits)) return 'visa';
  if (/^(5[1-5]|2[2-7])/.test(digits)) return 'mastercard';
  if (/^3[47]/.test(digits)) return 'amex';
  if (/^(60|65|81|82|508)/.test(digits)) return 'rupay';
  return 'card';
}

/** Luhn checksum for card numbers. */
export function isValidCardNumber(number: string): boolean {
  const digits = number.replace(/\D/g, '');
  if (digits.length < 12 || digits.length > 19) return false;
  let sum = 0;
  let double = false;
  for (let index = digits.length - 1; index >= 0; index -= 1) {
    let digit = Number(digits[index]);
    if (double) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
    double = !double;
  }
  return sum % 10 === 0;
}

export function isFutureExpiry(month: number, year: number, now = new Date()): boolean {
  if (!Number.isInteger(month) || month < 1 || month > 12) return false;
  const fullYear = year < 100 ? 2000 + year : year;
  const endOfMonth = new Date(fullYear, month, 1).getTime();
  return endOfMonth > now.getTime();
}

// ---------- addresses ----------

/** Validate and normalize an address from a form (customer app) or callable. Never throws. */
export function validateAddressFields(raw: unknown): ValidationResult<AddressFields> {
  const input = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
  const errors: Partial<Record<keyof AddressFields | 'form', string>> = {};

  const name = cleanText(input.name, 80);
  if (!name) errors.name = 'Enter the recipient name.';
  const phone = typeof input.phone === 'string' ? normalizePhone(input.phone) : null;
  if (!phone) errors.phone = 'Enter a valid mobile number.';
  const line1 = cleanText(input.line1, 160);
  if (!line1 || line1.length < 5) errors.line1 = 'Enter the house number and street.';
  const city = cleanText(input.city, 60);
  if (!city) errors.city = 'Enter the city.';
  const zip = typeof input.zip === 'string' ? input.zip.replace(/\s/g, '') : '';
  if (!/^[A-Za-z0-9-]{3,10}$/.test(zip)) errors.zip = 'Enter a valid PIN / ZIP code.';
  const location = input.location == null ? null : isValidLatLng(input.location) ? input.location : undefined;
  if (location === undefined) errors.location = 'The map location is invalid.';

  if (Object.keys(errors).length > 0) return { ok: false, errors };
  return {
    ok: true,
    value: {
      label: cleanText(input.label, 20) ?? 'Home',
      name: name!,
      phone: phone!,
      line1: line1!,
      line2: cleanText(input.line2, 160),
      landmark: cleanText(input.landmark, 100),
      city: city!,
      zip,
      location: location ?? null,
    },
  };
}

/** One-line address for labels and the delivery record. */
export function formatAddress(address: Pick<AddressFields, 'line1' | 'line2' | 'city' | 'zip'>): string {
  return [address.line1, address.line2, address.city, address.zip].filter(Boolean).join(', ');
}
